// SPDX-License-Identifier: MIT
//
// Sigmoid stepper moves generated by a timer and a DMA channel: every STEP edge comes from the
// timer's compare output, every step period from the DMA, the CPU only refills a buffer every
// `Chunk` steps. No interrupt per step, no jitter from interrupt latency.
//
//   STEP pin = timer channel Ch in toggle mode (one edge per step: TMC2209 DEDGE), CCR = 1:
//   the edge comes one tick after each update event. The DMA writes the next period into ARR
//   (preload) at every update. The last item ends the move: its transfer-complete interrupt
//   switches on one-pulse mode, the counter stops at the next update - after the last edge.
//
//   using StepTimer = stm32h5::Timer<TimerId::Tim3, {.kernel_hz = clocks.timer1_hz(), .tick_hz = 1'000'000}>;
//   using StepDma = stm32h5::DmaChannel<{.channel = 4, .request = DmaRequest::Tim3Up,
//                                        .direction = DmaDirection::MemoryToPeripheral,
//                                        .memory_bytes = 2, .peripheral_bytes = 4}>;
//   RTOS_DMA_BUFFER TimerStepper<StepTimer, 1, StepDma, ramp> stepper;   // buffers in DMA memory
//   stepper.init();
//   stepper.start(2000);
//   DMA channel ISR: stepper.on_dma_irq();    timer ISR: if (stepper.on_timer_irq()) { done }
//
// Timeline of a move of N steps with periods p0 .. pN-1 (ticks), A = ARR:
//   start: A = p0 active (update by software), A = p1 - 1 preloaded, CNT = 2 (past the match,
//          so no edge at the start): edge 1 after p0 ticks
//   update k (1 .. N): A = p(k) - 1 becomes active, the DMA preloads the one after it; edge k
//          one tick later. Item k (A for period k + 1) of N items; items past the move repeat the
//          last period (the timer still needs one).
//   DMA complete at update N: one-pulse mode on; update N + 1 stops the counter, raises the
//          timer interrupt: move done.
// Deadlines for the interrupts: the DMA interrupt must start the next chunk, and set one-pulse
// mode, within one step period (at cruise rate). Give it a high priority.
#pragma once

#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <type_traits>

#include "rtos/motion/profile_stepper.hpp"
#include "rtos/motion/sigmoid_stepper.hpp"

namespace rtos::motion {

/// `Tim`: a stm32h5::Timer with ARR preload; `Ch` its channel on the STEP pin; `Dma`: a
/// stm32h5::DmaChannel, memory to peripheral, paced by the timer's update request. `M`: the
/// motion plan - begin(steps) -> first period, period(k), total() - a SigmoidStepper (ramp fixed
/// by the compiler: TimerStepper below) or a ProfileStepper (ramp chosen at run time: motion()).
template <class Tim, unsigned Ch, class Dma, class M, std::size_t Chunk = 32>
class BasicTimerStepper {
    using Item = std::conditional_t<Dma::config.memory_bytes == 4, std::uint32_t, std::uint16_t>;
    static_assert(Dma::config.memory_bytes == 2 || Dma::config.memory_bytes == 4, "items of 2 or 4 bytes");
    static_assert(Dma::config.peripheral_bytes == 4, "ARR is written as a 32-bit register");
    static_assert(Tim::preload, "the timer needs ARR preload (ARPE): the DMA writes the next period");
    static_assert(Chunk >= 2 && Chunk * sizeof(Item) <= 0xFFFF);

public:
    using Motion = M;
    /// The longest step period ARR and a DMA item hold (a run-time profile is checked against it).
    static constexpr std::uint32_t max_ticks =
        Tim::max_period < (Dma::config.memory_bytes == 2 ? 0xFFFFu : 0xFFFF'FFFFu) ? Tim::max_period
                                                                                    : (Dma::config.memory_bytes == 2 ? 0xFFFFu : 0xFFFF'FFFFu);

    /// The motion plan, to configure a run-time profile - only while no move runs (false otherwise).
    [[nodiscard]] Motion* motion() noexcept { return moving() ? nullptr : &plan_; }

    /// Timer output (toggle on CCR = 1), DMA channel; the counter stays stopped.
    void init() noexcept {
        Tim::init();
        Tim::template set_compare<Ch>(1);
        Tim::template configure_toggle<Ch>();
        Dma::init();
    }

    /// Start a move of `steps` (sign = direction; set the DIR pin first). False if a move is
    /// running or there is nothing to do.
    bool start(std::int32_t steps) noexcept {
        if (moving_.load(std::memory_order_acquire) || steps == 0) {
            return false;
        }
        const std::uint32_t p0 = plan_.begin(steps);
        total_ = plan_.total();
        forward_ = steps > 0;
        Tim::stop();
        Tim::disable_update_dma();
        Tim::disable_update_irq();
        Tim::set_one_pulse(false);
        Dma::stop();

        Tim::set_period(p0 + 1);  // ARR = p0: CNT runs 2 .. p0, then 0, 1 -> edge 1 after p0
        Tim::generate_update();
        Tim::set_period(arr(1) + 1u);  // preloaded: the period of step 1
        Tim::set_counter(2);
        (void)Tim::take_update();  // the UIF of the software update

        produced_ = 0;
        finished_items_ = 0;
        fill(0);
        fill(1);
        active_ = 0;
        moving_.store(true, std::memory_order_release);
        (void)Dma::start(Tim::arr_address(), buffer_[0].data(), count_[0], /*interrupt*/ true);
        Tim::enable_update_dma();
        Tim::start();
        return true;
    }

    /// GPDMA channel interrupt: the next chunk, or the end of the move.
    void on_dma_irq() noexcept {
        Dma::clear();
        if (!moving_.load(std::memory_order_relaxed)) {
            return;
        }
        finished_items_ += count_[active_];
        if (finished_items_ >= total_) {
            // update N happened: stop at update N + 1, after the last edge
            Tim::set_one_pulse(true);
            (void)Tim::take_update();
            Tim::enable_update_irq();
            return;
        }
        const std::size_t next = 1 - active_;
        (void)Dma::start(Tim::arr_address(), buffer_[next].data(), count_[next], true);
        const std::size_t done = active_;
        active_ = next;
        fill(done);
    }

    /// Timer interrupt: true once, when the move has ended (the counter stopped).
    bool on_timer_irq() noexcept {
        if (!Tim::take_update()) {
            return false;
        }
        Tim::disable_update_irq();
        Tim::disable_update_dma();
        Tim::set_one_pulse(false);
        position_ += forward_ ? static_cast<std::int32_t>(total_) : -static_cast<std::int32_t>(total_);
        moving_.store(false, std::memory_order_release);
        return true;
    }

    /// Abort a move at once (the steps done so far count).
    void stop() noexcept {
        if (!moving_.load(std::memory_order_acquire)) {
            return;
        }
        Tim::stop();
        const std::uint32_t done = steps_done();
        Dma::stop();
        Tim::disable_update_dma();
        Tim::disable_update_irq();
        Tim::set_one_pulse(false);
        position_ += forward_ ? static_cast<std::int32_t>(done) : -static_cast<std::int32_t>(done);
        moving_.store(false, std::memory_order_release);
    }

    [[nodiscard]] bool moving() const noexcept { return moving_.load(std::memory_order_acquire); }
    [[nodiscard]] bool forward() const noexcept { return forward_; }
    /// Position in steps; while moving, counted from the DMA progress (an update event = one
    /// edge, the edge follows one tick later).
    [[nodiscard]] std::int32_t position() const noexcept {
        if (!moving()) {
            return position_;
        }
        const auto done = static_cast<std::int32_t>(steps_done());
        return position_ + (forward_ ? done : -done);
    }
    void set_position(std::int32_t p) noexcept { position_ = p; }
    [[nodiscard]] const Motion& plan() const noexcept { return plan_; }

private:
    /// ARR for period k >= 1 of the move: p(k) - 1; past the last step the last period again.
    [[nodiscard]] Item arr(std::uint32_t k) const noexcept {
        return static_cast<Item>(plan_.period(k < total_ ? k : total_ - 1) - 1u);
    }

    /// Next items into buffer b: item i is the ARR of period i + 2 (written at update i + 1).
    void fill(std::size_t b) noexcept {
        std::size_t n = 0;
        while (n < Chunk && produced_ < total_) {
            buffer_[b][n++] = arr(produced_ + 2);
            ++produced_;
        }
        count_[b] = n;
    }

    [[nodiscard]] std::uint32_t steps_done() const noexcept {
        const std::uint32_t left = Dma::remaining() / sizeof(Item);
        const std::uint32_t in_chunk = static_cast<std::uint32_t>(count_[active_]) - (left < count_[active_] ? left : 0);
        const std::uint32_t done = finished_items_ + in_chunk;
        return done < total_ ? done : total_;
    }

    std::array<std::array<Item, Chunk>, 2> buffer_{};
    std::array<std::size_t, 2> count_{};
    std::size_t active_ = 0;
    Motion plan_;
    std::uint32_t total_ = 0, produced_ = 0, finished_items_ = 0;
    std::int32_t position_ = 0;
    bool forward_ = true;
    std::atomic<bool> moving_{false};
};

/// The ramp fixed by the compiler (SigmoidRamp R): its slowest step is checked at compile time.
template <class Tim, unsigned Ch, class Dma, SigmoidRamp R, std::size_t Chunk = 32>
class TimerStepper : public BasicTimerStepper<Tim, Ch, Dma, SigmoidStepper<R>, Chunk> {
    static_assert(Tim::tick_hz == R.tick_hz, "timer ticks and ramp ticks differ");
    static_assert(SigmoidStepper<R>::max_ticks <= Tim::max_period, "the slowest step does not fit ARR");
    static_assert(SigmoidStepper<R>::max_ticks <= (Dma::config.memory_bytes == 2 ? 0xFFFFu : 0xFFFF'FFFFu),
                  "the slowest step does not fit a DMA item");
};

/// The ramp chosen at run time: motion()->configure(profile, Tim::tick_hz, max_ticks) between moves.
template <class Tim, unsigned Ch, class Dma, std::size_t Chunk = 32>
using ProfileTimerStepper = BasicTimerStepper<Tim, Ch, Dma, ProfileStepper, Chunk>;

}  // namespace rtos::motion
